// The one mulberry32 + FNV-1a. The generators (scripts/fixtures), kettle-to-v3.ts and scan-demo.mjs seed from here; changing a
// constant changes every generated byte. Four gates notice: check:data (kettle-to-v3.ts --check) and
// check:findings (kettle-findings.mjs --check) for `seeded`, and check:kettle-data / check:swarm-data
// (gen-kettle.mjs --check, gen-swarm.mjs --check) for `mulberry32`, whose output nothing diffed until
// 2026-10-21 — a change to it left the whole gate green with the committed fixtures no longer reproducible.

/** FNV-1a, 32 bit. */
export function hash(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return h >>> 0;
}
/** mulberry32: a () => [0, 1) stream from a 32-bit integer seed. */
export function mulberry32(seed: number): () => number {
  let a = seed | 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
/** mulberry32 seeded by a string. */
export const seeded = (seed: string): (() => number) => mulberry32(hash(seed));
